vibrant.tokens:
/* design-systems/vibrant/tokens.css
 * Structured token bindings for Vibrant.
 * vibrant visual system with saturated accents, warm surfaces, and optimistic product energy.
 */

:root {
  --bg: #fff8d7;
  --surface: #ffffff;
  --surface-warm: #ffef9f;
  --fg: #1d1836;
  --fg-2: #4c426c;
  --muted: #796f91;
  --meta: #ff6b00;
  --border: #eadfba;
  --border-soft: #f5eccd;
  --accent: #ff6b00;
  --accent-on: #ffffff;
  --accent-hover: color-mix(in oklab, var(--accent), black 8%);
  --accent-active: color-mix(in oklab, var(--accent), black 14%);
  --success: #2e9d57;
  --warn: #ffb020;
  --danger: #e5484d;
  --font-display: Inter, system-ui, sans-serif;
  --font-body: Inter, system-ui, sans-serif;
  --font-mono: "SF Mono", ui-monospace, Menlo, monospace;
  --text-xs: 12px;
  --text-sm: 14px;
  --text-base: 16px;
  --text-lg: 18px;
  --text-xl: 24px;
  --text-2xl: 36px;
  --text-3xl: 54px;
  --text-4xl: 76px;
  --leading-body: 1.52;
  --leading-tight: 1.06;
  --tracking-display: -0.025em;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-12: 48px;
  --section-y-desktop: 96px;
  --section-y-tablet: 68px;
  --section-y-phone: 48px;
  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-pill: 9999px;
  --elev-flat: none;
  --elev-ring: 0 0 0 1px var(--border);
  --elev-raised: 0 18px 44px rgba(29, 24, 54, 0.14);
  --focus-ring: 0 0 0 4px rgba(255, 107, 0, 0.26);
  --motion-fast: 150ms;
  --motion-base: 240ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --container-max: 1180px;
  --container-gutter-desktop: 36px;
  --container-gutter-tablet: 24px;
  --container-gutter-phone: 16px;
}

