raycast.tokens:
/* ─────────────────────────────────────────────────────────────────────────
 * design-systems/raycast/tokens.css
 *
 * Structured token bindings for the "Raycast" brand — the macOS-native
 * command palette / launcher's precision desktop-instrument voice.
 *
 * Brand identity in three sentences:
 *   1. Near-black blue-tinted canvas (#07080a) — not pure black — with
 *      semi-transparent white borders (0.06 opacity) and multi-layer
 *      inset shadows that simulate physical glass-key depth.
 *   2. Inter everywhere with OpenType "calt","kern","liga","ss03"; the
 *      signature move is positive +0.2px letter-spacing on body for an
 *      airy dark-mode rhythm, weight 500 as the readable body baseline.
 *   3. Raycast Red (#FF6363) is punctuation, not pervasive — hero
 *      stripes and danger states only. Raycast Blue (hsl(202,100%,67%))
 *      carries interactive focus / links so red can stay scarce.
 *
 * Schema decisions:
 *   - --bg #07080a (blue-cold near-black) / --surface #101111 (Surface 100).
 *   - --surface-warm aliases --surface (cold-dark system, no warm tier).
 *   - --fg #f9f9f9 near-white (avoids pure-white eye-strain on void).
 *   - --fg-2 #cecece light-gray body / --meta #6a6b6c dim-gray metadata.
 *   - --border rgba(255,255,255,0.06) — the "barely visible, structurally
 *     essential" containment line called out in DESIGN.md §7.
 *   - --accent #FF6363 (Raycast Red); hover/active shift tone, not opacity
 *     (opacity 0.6 is a component-level interaction pattern, not a token).
 *   - --focus-ring uses Raycast Blue, not accent red — separating brand
 *     punctuation from interactive feedback is core to the system.
 *   - --elev-ring is the macOS signature double-ring (outer #1b1c1e
 *     + inset #07080a) that replaces traditional 1px borders on cards.
 *   - --radius-sm 6px (workhorse: buttons / badges), --radius-md 12px
 *     (standard cards), --radius-lg 16px (large feature containers).
 * ─────────────────────────────────────────────────────────────────── */

:root {
  /* ─── Surface ──────────────────────────────────────────────────── */
  --bg:           #07080a;              /* near-black blue tint — the void */
  --surface:      #101111;              /* Surface 100 — elevated cards */
  --surface-warm: var(--surface);       /* no warm tier in cold dark system */

  /* ─── Foreground ───────────────────────────────────────────────── */
  --fg:    #f9f9f9;                     /* near-white primary text */
  --fg-2:  #cecece;                     /* light gray secondary body */
  --muted: #9c9c9d;                     /* medium gray tertiary / nav links */
  --meta:  #6a6b6c;                     /* dim gray placeholders / metadata */

  /* ─── Border ───────────────────────────────────────────────────── */
  --border:      rgba(255, 255, 255, 0.06);   /* card containment — barely visible */
  --border-soft: rgba(255, 255, 255, 0.04);   /* inner row separator */

  /* ─── Accent ───────────────────────────────────────────────────── */
  --accent:        #FF6363;             /* Raycast Red — hero stripes, error states */
  --accent-on:     #ffffff;
  --accent-hover:  #ff7777;             /* lighter tone for hover */
  --accent-active: #e85757;             /* darker tone for pressed */

  /* ─── Semantic ─────────────────────────────────────────────────── */
  --success: hsl(151, 59%, 59%);        /* Raycast Green */
  --warn:    hsl(43, 100%, 60%);        /* Raycast Yellow */
  --danger:  hsl(0, 100%, 69%);         /* Error Red (≈ #FF6363) */

  /* ─── Typography ───────────────────────────────────────────────── */
  --font-display: "Inter", "Inter Fallback", "SF Pro Display", -apple-system, system-ui, "Segoe UI", Roboto, sans-serif;
  --font-body:    "Inter", "Inter Fallback", "SF Pro Text", -apple-system, system-ui, "Segoe UI", Roboto, sans-serif;
  --font-mono:    "GeistMono", ui-monospace, "SF Mono", "Roboto Mono", Menlo, Monaco, Consolas, monospace;

  /* Type scale — DESIGN.md §3 Typography Hierarchy.
   * Display Hero (64px) → text-4xl; Section Display (≈40–56px) → text-3xl;
   * Section Heading (24px) → text-2xl; Sub-heading (20px) → text-xl;
   * Body Large (18px) → text-lg; Body (16px) → text-base;
   * Caption (14px) → text-sm; Small (12px) → text-xs. */
  --text-xs:   12px;
  --text-sm:   14px;
  --text-base: 16px;
  --text-lg:   18px;
  --text-xl:   20px;
  --text-2xl:  24px;
  --text-3xl:  40px;
  --text-4xl:  64px;

  /* Leading + tracking.
   * --leading-body 1.6: DESIGN.md "Body 16/500/1.60" — relaxed dark rhythm.
   * --leading-tight 1.1: hero hugs its baseline.
   * --tracking-display 0px: hero is zero-tracked; body inline adds +0.2px
   * (the signature Raycast move noted in DESIGN.md §3 Principles). */
  --leading-body:     1.6;
  --leading-tight:    1.1;
  --tracking-display: 0px;

  /* ─── Spacing ──────────────────────────────────────────────────── */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  20px;
  --space-6:  24px;
  --space-8:  32px;
  --space-12: 48px;

  /* Section rhythm — DESIGN.md §5 "80–120px vertical between sections".
   * The dramatic negative space is the cinematic pacing of the system. */
  --section-y-desktop: 96px;
  --section-y-tablet:  64px;
  --section-y-phone:   40px;

  /* ─── Radius ───────────────────────────────────────────────────── */
  /* 6px is the workhorse (buttons, badges); 12px standard cards;
   * 16px large feature containers; pill (9999px) for primary CTAs
   * — DESIGN.md uses 86px+ which is functionally pill at all sizes. */
  --radius-sm:   6px;
  --radius-md:   12px;
  --radius-lg:   16px;
  --radius-pill: 9999px;

  /* ─── Elevation ────────────────────────────────────────────────── */
  /* macOS-native shadow philosophy: outer rings replace borders, inset
   * highlights simulate light from above, inset darks simulate shadow
   * underneath. --elev-ring is the signature double-ring: outer card-
   * surface tone + inset deep-bg tone, creating physical containment. */
  --elev-flat:   none;
  --elev-ring:   rgb(27, 28, 30) 0px 0px 0px 1px, rgb(7, 8, 10) 0px 0px 0px 1px inset;
  --elev-raised:
    rgba(255, 255, 255, 0.05) 0px 1px 0px 0px inset,
    rgba(0, 0, 0, 0.28) 0px 1.189px 2.377px,
    0 0 0 1px rgba(255, 255, 255, 0.06);

  /* ─── Focus ────────────────────────────────────────────────────── */
  /* Raycast Blue, not accent red — DESIGN.md §2 reserves red for hero
   * stripes / danger and blue for interactive / focus / links. Keeping
   * focus blue protects the scarcity of the red. */
  --focus-ring: 0 0 0 3px hsla(202, 100%, 67%, 0.35);

  /* ─── Motion ───────────────────────────────────────────────────── */
  --motion-fast:   150ms;
  --motion-base:   200ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);

  /* ─── Layout ───────────────────────────────────────────────────── */
  --container-max:            1200px;
  --container-gutter-desktop: 24px;
  --container-gutter-tablet:  16px;
  --container-gutter-phone:   12px;
}

superhuman.tokens:
/* ─────────────────────────────────────────────────────────────────────────
 * design-systems/superhuman/tokens.css
 *
 * Structured token bindings for "Design System Inspired by Superhuman".
 * Premium keyboard-first email client. Predominantly white canvas with a
 * single dramatic gesture of color (deep purple hero), warm cream CTAs,
 * lavender as the sole accent, and charcoal ink (warmer than #000) for text.
 *
 * Brand identity in three sentences:
 *   1. Maximum confidence through minimum decoration — white dominates,
 *      borders define containers, shadows are whispered. Lavender Glow
 *      (#cbb7fb) is the only accent that ever leaves the warm-neutral
 *      grayscale.
 *   2. Super Sans VF with non-standard weight stops (460 / 540 / 600 / 700).
 *      Body weight is 460 — slightly heavier than regular but lighter than
 *      medium — the typographic signature that feels confident, never bold.
 *   3. Two-radius binary system (8px / 16px) and ultra-tight 0.96 leading
 *      on display sizes — headlines compress into architectural blocks
 *      while body text breathes at 1.50 leading.
 *
 * Schema decisions:
 *   - --bg: #ffffff (Pure White) — the dominant content canvas.
 *   - --surface: #ffffff — cards inherit the canvas; --border defines them.
 *   - --surface-warm: #e9e5dd (Warm Cream) — lifted warm tier for CTAs.
 *   - --fg: #292827 (Charcoal Ink) — warm near-black, never pure black.
 *   - --fg-2 → var(--fg) — DESIGN.md uses one ink color on light surfaces.
 *   - --muted: #6f6c69 — warm mid-gray for captions, derived to sit
 *     between Charcoal Ink and Parchment Border on the warm hue family.
 *   - --border: #dcd7d3 (Parchment Border) — warm light gray, slight pink.
 *   - --accent: #cbb7fb (Lavender Glow); --accent-on: #292827 — charcoal
 *     on lavender (DESIGN.md "Don't use bright/saturated CTA text").
 *   - --leading-tight: 0.96 — the signature display compression.
 *   - --tracking-display: -0.0275em ≈ -1.32px / 48px (DESIGN.md §3).
 *   - --radius-md: 8px (no mid-tier — DESIGN.md mandates only 8 / 16).
 *   - --elev-raised: charcoal-tinted whisper, never gray; matches the
 *     warm-neutral palette used everywhere else.
 * ─────────────────────────────────────────────────────────────────── */

:root {
  /* ─── Surface ─────────────────────────────────────────────────────
   * White canvas dominates. Warm Cream (#e9e5dd) lives in --surface-warm
   * as the lifted warm tier — reserved for CTAs, never used as a card bg. */
  --bg: #ffffff;             /* Pure White — primary page background */
  --surface: #ffffff;        /* Cards inherit the canvas; --border contains them */
  --surface-warm: #e9e5dd;   /* Warm Cream — primary button background only */

  /* ─── Foreground ──────────────────────────────────────────────────
   * Charcoal Ink — warm near-black with faint brown undertone. Body
   * text uses one ink color throughout; --muted is reserved for true
   * subtext like captions and helper labels. */
  --fg: #292827;             /* Charcoal Ink — primary text */
  --fg-2: var(--fg);         /* alias — DESIGN.md uses one ink for body */
  --muted: #6f6c69;          /* Warm mid-gray — captions, helper text */
  --meta: var(--muted);      /* alias — same warm gray for metadata */

  /* ─── Border ──────────────────────────────────────────────────────
   * Parchment Border — warm light gray with slight pink undertone.
   * Cards rely on borders for containment, not box shadows. */
  --border: #dcd7d3;         /* Parchment Border — card edges, dividers */
  --border-soft: var(--border); /* alias — no separate inner-row tier */

  /* ─── Accent ──────────────────────────────────────────────────────
   * Lavender Glow — soft, approachable purple. The ONLY chromatic
   * departure from the warm-neutral palette. Charcoal sits on it for
   * AA contrast (lavender is too light for white text). */
  --accent: #cbb7fb;
  --accent-on: #292827;      /* Charcoal on lavender — DESIGN.md §4 */
  --accent-hover: color-mix(in oklab, var(--accent), black 6%);
  --accent-active: color-mix(in oklab, var(--accent), black 12%);

  /* ─── Semantic ────────────────────────────────────────────────────
   * Superhuman's marketing exercises extreme color restraint, but the
   * schema requires semantic tokens for product-side usage (status pills,
   * inline validation). Defaults from _schema/defaults.css; legible on white. */
  --success: #16a34a;
  --warn: #eab308;
  --danger: #dc2626;

  /* ─── Typography ──────────────────────────────────────────────────
   * Super Sans VF — custom variable font with non-standard weight axis
   * (460, 540, 600, 700). Body weight is 460 — the signature stop that
   * sits between Regular and Medium. Fallback chain mirrors DESIGN.md §3. */
  --font-display: "Super Sans VF", system-ui, -apple-system, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
  --font-body: "Super Sans VF", system-ui, -apple-system, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Fira Sans", "Droid Sans", "Helvetica Neue", sans-serif;
  --font-mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Monaco, Consolas, monospace;

  /* Type scale — DESIGN.md §3 hierarchy. 64px hero / 48px section /
   * 28px feature title / 22px card heading / 20px body heading.
   * All eight stops appear verbatim in DESIGN.md — no interpolation. */
  --text-xs: 12px;           /* Micro Label */
  --text-sm: 14px;           /* Caption family */
  --text-base: 16px;         /* Body / Button / Nav */
  --text-lg: 20px;           /* Body Heading */
  --text-xl: 22px;           /* Card Heading */
  --text-2xl: 28px;          /* Feature Title */
  --text-3xl: 48px;          /* Section Heading */
  --text-4xl: 64px;          /* Display Hero */

  /* Leading + tracking.
   * 0.96 — the signature display compression (DESIGN.md §3).
   * 1.50 — body text breathes generously by contrast.
   * -0.0275em ≈ -1.32px / 48px from DESIGN.md §3, applied at display sizes only. */
  --leading-body: 1.5;
  --leading-tight: 0.96;
  --tracking-display: -0.0275em;

  /* ─── Spacing ─────────────────────────────────────────────────────
   * 8px base. Scale per DESIGN.md §5: 4 / 8 / 12 / 16 / 20 / 24 / 32 / 48. */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-12: 48px;

  /* Section rhythm — DESIGN.md §5 says 48–80px between major sections.
   * Top of the range on desktop, compresses on smaller breakpoints. */
  --section-y-desktop: 80px;
  --section-y-tablet: 56px;
  --section-y-phone: 40px;

  /* ─── Radius ──────────────────────────────────────────────────────
   * Binary system — DESIGN.md §5: only 8px and 16px exist on the
   * marketing site. No micro-rounding (2px), no pill buttons (50px+).
   * --radius-md collapses to --radius-sm because the brand has no
   * mid-tier; --radius-pill is reserved for status dots only. */
  --radius-sm: 8px;          /* Buttons, inputs, inline elements */
  --radius-md: 8px;          /* No mid-tier — DESIGN.md mandates only 8/16 */
  --radius-lg: 16px;         /* Cards, links, larger containers */
  --radius-pill: 9999px;     /* Status dots only — never buttons */

  /* ─── Elevation ───────────────────────────────────────────────────
   * Depth lives in borders and color contrast, not shadow. The raised
   * tier is a charcoal-tinted whisper for product-screenshot frames
   * (DESIGN.md §6 "Subtle shadow … product screenshot containers"). */
  --elev-flat: none;
  --elev-ring: 0 0 0 1px var(--border);
  --elev-raised: 0 2px 12px rgba(41, 40, 39, 0.06);

  /* ─── Focus ring ──────────────────────────────────────────────────
   * Lavender Glow at 45% — Superhuman is keyboard-first, so the focus
   * indicator must read clearly without violating the muted palette. */
  --focus-ring: 0 0 0 3px color-mix(in oklab, var(--accent), transparent 55%);

  /* ─── Motion ──────────────────────────────────────────────────────
   * Restrained — Superhuman's velocity is in the keyboard, not the page.
   * Defaults from _schema/defaults.css. */
  --motion-fast: 150ms;
  --motion-base: 200ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);

  /* ─── Layout ──────────────────────────────────────────────────────
   * 1200px container — DESIGN.md §5 "~1200px content container, centered". */
  --container-max: 1200px;
  --container-gutter-desktop: 24px;
  --container-gutter-tablet: 16px;
  --container-gutter-phone: 12px;
}

warp.tokens:
/* ─────────────────────────────────────────────────────────────────────────
 * design-systems/warp/tokens.css
 *
 * Structured token bindings for "Design System Inspired by Warp".
 * Warm dark canvas, near-black like charred wood. Almost monochromatic
 * warm grays. Matter Regular (weight 400) carries every tier — even
 * the 80px hero. Restraint through warmth.
 *
 * Key brand decisions encoded here:
 *   - Warm near-black canvas (#161412) — never cold/blue dark
 *   - Warm Parchment (#faf9f6) text — barely-cream, never pure white
 *   - Earth Gray (#353534) as the brand "accent" — the dark pill CTA
 *     IS the brand signal; no chromatic accent (DESIGN.md §2 forbids)
 *   - Four-tier text system: parchment → ash → stone → muted-purple
 *   - Mist Border (rgba(226, 226, 226, 0.35)) for ghostly containment
 *   - Pill radius reserved for primary CTA; cards stay at 12–14px
 *   - Almost-flat elevation — depth via borders + opacity, not shadow
 *   - Focus ring uses the FG (parchment), not a colored glow — DESIGN.md
 *     "Border brightness increase, no colored rings"
 * ─────────────────────────────────────────────────────────────────── */

:root {
  /* ─── Surface ─────────────────────────────────────────────────────
   * Deep warm void. Pure black would feel cold; the reddish-earthen
   * undertone (R>G>B, all near 20) makes the canvas feel like charred
   * wood. Surface is bg + a perceptual ~4% lift, matching the
   * "Frosted Veil" rgba(255,255,255,0.04) overlay DESIGN.md describes. */
  --bg: #161412;             /* Deep Void — warm near-black, earth-toned */
  --surface: #1f1d1b;        /* Frosted Veil resolved over bg */
  --surface-warm: var(--surface); /* alias — already warm; no separate tier */

  /* ─── Foreground ──────────────────────────────────────────────────
   * Four warm tiers, no cool grays. Parchment is the headline tone —
   * its barely-cream undertone is what makes the dark canvas feel
   * inviting rather than austere. Meta carries Purple-Tint Gray, the
   * underlined-link tone DESIGN.md §2 calls out. */
  --fg: #faf9f6;             /* Warm Parchment — primary headlines */
  --fg-2: #afaeac;           /* Ash Gray — body paragraphs, button text */
  --muted: #868584;          /* Stone Gray — secondary descriptions */
  --meta: #666469;           /* Purple-Tint Gray — links, tertiary content */

  /* ─── Border ──────────────────────────────────────────────────────
   * Semi-transparent borders create the "ghostly containment" Warp
   * uses instead of shadows. 35% opacity is the canonical value;
   * inner separators alias to the same line — the brand never uses
   * a stronger or weaker tier (monochromatic restraint). */
  --border: rgba(226, 226, 226, 0.35); /* Mist Border */
  --border-soft: var(--border);        /* alias — single border tier */

  /* ─── Accent ──────────────────────────────────────────────────────
   * Warp's "accent" is restrained: Earth Gray, the dark pill CTA bg.
   * DESIGN.md §2 explicitly forbids bold accent colors — interactive
   * states are communicated through opacity and underline, never hue.
   * accent-on is Ash Gray (#afaeac), the muted button-text color
   * DESIGN.md §4 specifies for the dark pill. */
  --accent: #353534;
  --accent-on: #afaeac;
  --accent-hover: #454545;   /* Dark Charcoal — slightly lighter pill */
  --accent-active: color-mix(in oklab, var(--accent), black 14%);

  /* ─── Semantic ────────────────────────────────────────────────────
   * Warp's marketing site has no surfaced semantic colors — these
   * exist only for component-level state messaging. Schema defaults
   * are accepted as-is to keep the warm palette unburdened. */
  --success: #16a34a;
  --warn: #eab308;
  --danger: #dc2626;

  /* ─── Typography ──────────────────────────────────────────────────
   * Matter is the entire system: geometric sans with soft character,
   * approachable in a way most developer-tool fonts are not. Inter
   * appears in DESIGN.md §3 as the "UI supplement" fallback before
   * generic system sans. Geist Mono is the code/terminal display
   * face; Matter Mono is the prose-aligned mono companion. */
  --font-display: "Matter Regular", "Matter", "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-body: "Matter Regular", "Matter", "Inter", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Geist Mono", "Matter Mono Regular", ui-monospace, "SF Mono", Menlo, Monaco, Consolas, monospace;

  /* Type scale — DESIGN.md §3 hierarchy. Body baseline is 18px (not
   * the more conventional 16); Warp's editorial pacing wants more
   * breathing room per line. Display hero at 80px with -0.03em
   * tracking (≈ -2.4px) is the billboard moment. */
  --text-xs: 12px;           /* Small Label — uppercase 2.4px tracking */
  --text-sm: 14px;           /* Caption — uppercase 1.4px tracking */
  --text-base: 18px;         /* Body — DESIGN.md body baseline */
  --text-lg: 24px;           /* Body Heading */
  --text-xl: 32px;           /* Sub-heading */
  --text-2xl: 48px;          /* Section Heading */
  --text-3xl: 56px;          /* Section Display */
  --text-4xl: 80px;          /* Display Hero — billboard scale */

  --leading-body: 1.4;       /* Body Large lh — relaxed editorial */
  --leading-tight: 1.0;      /* Display Hero lh — maximum compression */
  --tracking-display: -0.03em; /* ≈ -2.4px at 80px — hero compression */

  /* ─── Spacing ─────────────────────────────────────────────────────
   * 8px base unit (DESIGN.md §5). Schema defaults match Warp's scale
   * exactly — no override needed. */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-12: 48px;

  /* ─── Section rhythm ──────────────────────────────────────────────
   * Generous, contemplative pacing. DESIGN.md §5: "80px–120px vertical
   * between major sections." Desktop uses the upper bound — Warp's
   * marketing site reads like a magazine, each section a page-turn. */
  --section-y-desktop: 120px;
  --section-y-tablet: 80px;
  --section-y-phone: 56px;

  /* ─── Radius ──────────────────────────────────────────────────────
   * Warp's radius scale (DESIGN.md §5) ranges 4–14px for content,
   * 50px+ for pills. Standard components live in the soft 6–14px tier;
   * the primary CTA reaches for --radius-pill. */
  --radius-sm: 6px;          /* Inputs, tags, small containers */
  --radius-md: 12px;         /* Feature cards */
  --radius-lg: 14px;         /* Large prominent containers */
  --radius-pill: 9999px;     /* Dark pill button — primary CTA */

  /* ─── Elevation ───────────────────────────────────────────────────
   * Almost-flat. DESIGN.md §6: "remarkably flat — almost zero shadow
   * usage." Depth comes from semi-transparent borders (the ring tier)
   * and the rare ambient shadow lifted directly from DESIGN.md's
   * inferred Level 3 treatment. */
  --elev-flat: none;
  --elev-ring: 0 0 0 1px var(--border);
  --elev-raised: 0 5px 15px rgba(0, 0, 0, 0.2);

  /* ─── Focus ring ──────────────────────────────────────────────────
   * NO colored ring. DESIGN.md §4: "Border brightness increase, no
   * colored rings (consistent with the monochromatic palette)." A
   * 50%-opacity warm parchment glow is the brightest legal indicator. */
  --focus-ring: 0 0 0 2px rgba(250, 249, 246, 0.5);

  /* ─── Motion ──────────────────────────────────────────────────────
   * Standard cadence — DESIGN.md doesn't specify timing, and the
   * brand's calm character is carried by typography and color rather
   * than animation choreography. Schema defaults preserved. */
  --motion-fast: 150ms;
  --motion-base: 200ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);

  /* ─── Layout ──────────────────────────────────────────────────────
   * 1500px container — DESIGN.md §5 calls out the breakpoint exactly.
   * Wide cinematic compositions let nature photography breathe; phone
   * gutter steps down through the responsive scale (32 → 24 → 16). */
  --container-max: 1500px;
  --container-gutter-desktop: 32px;
  --container-gutter-tablet: 24px;
  --container-gutter-phone: 16px;
}

shopify.tokens:
/* ─────────────────────────────────────────────────────────────────────────
 * design-systems/shopify/tokens.css
 *
 * Structured token bindings for the "Shopify" brand — dark-first cinematic,
 * ethereal ultra-light display type, neon green accent.
 *
 * Brand identity in three sentences:
 *   1. Darkness as theatre — deep forest-teal surfaces (not pure black:
 *      #000000 root, #02090A cards, #061A1C sections, #102620 elevated)
 *      create a nocturnal keynote atmosphere, staged like a product reveal.
 *   2. NeueHaasGrotesk variable at monumental scale (96px) with impossible
 *      lightness (weight 330–400, OpenType ss03); Inter Variable handles
 *      body at unusual weights (420/450/550); combined they feel etched.
 *   3. Neon Green (#36F4A4) is the singular high-energy accent — pulsing
 *      like a bioluminescent signal exclusively for focus rings and accent
 *      highlights; white is the only text color on dark.
 *
 * Schema decisions:
 *   - --bg: #000000 (void — root page background, true black).
 *   - --surface: #02090A (deep teal — card surfaces).
 *   - --surface-warm: #061A1C (dark forest — section backgrounds).
 *   - --fg: #ffffff (white — the only text color on dark).
 *   - --fg-2: #ffffff (same; no secondary ink split on dark canvas).
 *   - --muted: #a1a1aa (muted zinc — secondary text, descriptions).
 *   - --meta: #71717a (shade-50 — timestamps, tertiary info).
 *   - --border: #1e2c31 (dark card border); --border-soft: #3f3f46.
 *   - --accent: #36F4A4 (neon green — focus/accent only, not bg).
 *   - --accent-on: #000000 (black text on neon green).
 *   - --tracking-display: 0em (NeueHaasGrotesk at 96px tracks neutral).
 *   - --leading-tight: 1.00 (display XL line-height at 96px).
 *   - --radius-sm: 9999px (full pill for all CTAs per brand identity).
 * ─────────────────────────────────────────────────────────────────── */

:root {
  /* ─── Surface ──────────────────────────────────────────────────── */
  --bg:           #000000;             /* void — true black root */
  --surface:      #02090a;             /* deep teal — card surfaces */
  --surface-warm: #061a1c;             /* dark forest — section backgrounds */

  /* ─── Foreground ───────────────────────────────────────────────── */
  --fg:   #ffffff;                     /* white — only text color on dark */
  --fg-2: #ffffff;                     /* same; no secondary ink split */
  --muted: #a1a1aa;                    /* muted zinc — secondary text */
  --meta:  #71717a;                    /* shade-50 — timestamps, tertiary */

  /* ─── Border ───────────────────────────────────────────────────── */
  --border:      #1e2c31;             /* dark card border */
  --border-soft: #3f3f46;             /* shade-70 — subtle dividers */

  /* ─── Accent ───────────────────────────────────────────────────── */
  /* Neon Green is precious — focus rings and critical accent highlights only.
     It never fills large surfaces. --accent-on is black for contrast. */
  --accent:        #36f4a4;           /* neon green */
  --accent-on:     #000000;
  --accent-hover:  #2de097;           /* slightly darker neon on hover */
  --accent-active: color-mix(in oklab, var(--accent), black 14%);

  /* ─── Semantic ─────────────────────────────────────────────────── */
  --success: #36f4a4;                 /* neon green — success state */
  --warn:    #eab308;
  --danger:  #dc2626;

  /* ─── Typography ───────────────────────────────────────────────── */
  --font-display: "NeueHaasGrotesk", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-body:    "Inter Variable", "Inter", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --font-mono:    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;

  /* Type scale — DESIGN.md §Typography Hierarchy.
   * NeueHaasGrotesk from 96px (display XL) to 24px (heading 6).
   * Inter Variable from 20px (body large) to 12px (label).
   * Schema spine maps the key stops. */
  --text-xs:   12px;                  /* label — uppercase, wide-tracked */
  --text-sm:   14px;                  /* caption — metadata */
  --text-base: 18px;                  /* body — standard Inter reading */
  --text-lg:   20px;                  /* body large — lead paragraphs */
  --text-xl:   32px;                  /* heading 4 — card headings */
  --text-2xl:  48px;                  /* heading 3 — feature titles */
  --text-3xl:  70px;                  /* heading 1 — section titles */
  --text-4xl:  96px;                  /* display XL — cinematic hero */

  /* Leading + tracking.
   * --leading-tight=1.00: display XL at 96px.
   * h2 (70px) → 1.00; h3 (48px) → 1.14 per DESIGN.md.
   * --tracking-display: 0em (NeueHaasGrotesk tracks neutral at display).
   * NB: positive tracking (0.32px–2.4px) exists at smaller NeueHaas sizes
   * and is set inline in components.html. */
  --leading-body:     1.56;
  --leading-tight:    1.00;
  --tracking-display: 0em;

  /* ─── Spacing ──────────────────────────────────────────────────── */
  /* 8px base unit per DESIGN.md §Spacing System. */
  --space-1:  4px;
  --space-2:  8px;
  --space-3:  12px;
  --space-4:  16px;
  --space-5:  24px;
  --space-6:  28px;
  --space-8:  36px;
  --space-12: 64px;

  /* Section rhythm — theatrical pacing: vast dark expanse between sections. */
  --section-y-desktop: 96px;
  --section-y-tablet:  64px;
  --section-y-phone:   40px;

  /* ─── Radius ───────────────────────────────────────────────────── */
  /* Full pill for all primary CTAs — non-negotiable brand identity.
     Cards: 8px standard, 12px featured. */
  --radius-sm:   9999px;              /* full pill — all CTA buttons */
  --radius-md:   8px;                 /* standard cards, inputs */
  --radius-lg:   12px;                /* featured cards */
  --radius-pill: 9999px;

  /* ─── Elevation ────────────────────────────────────────────────── */
  /* Multi-layered shadow: 1px ring + progressive blur + inset white glow.
     Shadows are "ambient occlusion" on dark surfaces, not traditional lift. */
  --elev-flat:   none;
  --elev-ring:   0 0 0 1px var(--border);
  --elev-raised:
    rgba(0, 0, 0, 0.1) 0px 0px 0px 1px,
    rgba(0, 0, 0, 0.1) 0px 2px 2px,
    rgba(0, 0, 0, 0.1) 0px 4px 4px,
    rgba(0, 0, 0, 0.1) 0px 8px 8px,
    rgba(255, 255, 255, 0.03) 0px 1px 0px inset;

  /* ─── Focus ────────────────────────────────────────────────────── */
  /* Neon Green focus ring — 2px ring, brand signature. */
  --focus-ring: 0 0 0 2px #36f4a4;

  /* ─── Motion ───────────────────────────────────────────────────── */
  --motion-fast:   150ms;
  --motion-base:   200ms;
  --ease-standard: ease;

  /* ─── Layout ───────────────────────────────────────────────────── */
  --container-max:            1280px;
  --container-gutter-desktop: 64px;
  --container-gutter-tablet:  32px;
  --container-gutter-phone:   16px;
}

urdu.design:
# Urdu Modern (Indus Script System)

> Category: Editorial / Personal / Publication
Urdu-first digital experiences with native RTL support,Nastaliq typography, and bilingual harmony.

---

## 1. Visual Theme & Atmosphere

**"Digital Heritage"** — A clean, spacious, and respectful aesthetic that bridges traditional Urdu calligraphy and contemporary minimal design.

The system avoids visual clutter. Every component prioritizes **whitespace**, **legibility**, and the inherent elegance of the Nastaliq script. The color palette echoes the earth tones and cultural symbols of the Indus region. Typography is the protagonist; everything else supports readability and cultural authenticity.

**Design Philosophy:**
- Urdu is not a "regional variant" of another language; it's the primary voice
- RTL layout is not an afterthought; it's architecturally primary
- Nastaliq's vertical complexity demands generous spacing
- Cultural aesthetics (traditional patterns, warm earths) elevate the experience beyond generic tech UI

---

## 2. Color Palette (Cultural Modernism)

All colors are tested for WCAG AA contrast compliance (minimum 4.5:1 for body text, 3:1 for large text).

### Primary Colors

| Color | Hex | Name | Usage | WCAG Contrast (on Parchment) |
|-------|-----|------|-------|------------------------------|
| **Primary Brand** | `#0F595E` | Deep Teal / Jungle Green | CTAs, primary actions, headers | 8.4:1 ✅ AA |
| **Background** | `#F4F1EA` | Parchment / Off-White | Main canvas, card backgrounds | — |
| **Accent** | `#C05621` | Terracotta / Rust | Secondary CTAs, highlights, focus states | 4.05:1 ✅ AA(large) |
| **Text Primary** | `#1A202C` | Rich Slate | Body text, labels | 15.1:1 ✅ AAA |
| **Text Secondary** | `#4A5568` | Warm Grey | Secondary labels, captions | 3.56:1 ✅ UI Only |
| **Border** | `#E2E8F0` | Light Silver | Component borders, dividers | — |

### Why These Colors?

- **Deep Teal (#0F595E):** Represents trust, stability, and national identity. Inspired by SadaPay (Pakistani fintech) and traditional Urdu ink.
- **Parchment (#F4F1EA):** Warm white that mimics high-quality paper and reduces eye strain during long reading sessions (critical for editorial content).
- **Terracotta (#C05621):** Echoes traditional pottery from the Indus Valley. Used for emphasis without overwhelming.
- **Rich Slate (#1A202C):** Maximum contrast for Nastaliq text; the script's nuqtas (diacritical marks) demand dark, sharp color.

### Extended Palette (Semantic)

```css
:root {
  /* Primary */
  --color-primary: #0F595E;
  --color-primary-dark: #0D3F45;
  --color-primary-light: #2B7A82;

  /* Accent */
  --color-accent: #C05621;
  --color-accent-dark: #A03F1C;
  --color-accent-light: #E8754A;

  /* Backgrounds */
  --color-bg-primary: #F4F1EA;
  --color-bg-secondary: #FAFAF8;

  /* Text */
  --color-text-primary: #1A202C;
  --color-text-secondary: #4A5568;
  --color-text-tertiary: #718096;

  /* Status Colors */
  --color-success: #2D5B4A; /* Deep green */
  --color-warning: #C05621; /* Terracotta (doubles as warning) */
  --color-error: #8B3A3A;   /* Deep burgundy */
  --color-info: #2B7A82;    /* Light teal */

  /* Borders & Dividers */
  --color-border: #E2E8F0;
  --color-border-dark: #CBD5E0;
}
```

---

## 3. Typography (The Heart of the System)

Urdu typography is the foundational layer. The system enforces **Bilingual Harmony** — Urdu takes priority; Latin text plays a supporting role.

### Font Families

#### Urdu Script (Primary)

```css
font-family: "Noto Nastaliq Urdu", "Mehr Nastaliq", "URW Chancery", serif;
```

**Font Selection Rationale:**
- **Noto Nastaliq Urdu** (Google Fonts): Professionally maintained, open-source, optimized for modern screens. Heavy weight (700) gives proper authority.
- **Mehr Nastaliq**: Pakistani-developed alternative; excellent Urdu-specific kerning.
- **URW Chancery** (system fallback): Hand-drawn serif; graceful degradation when web fonts fail.

**Import (add to `<head>`):**
```html
<link rel="preload" href="https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;700&display=swap" as="style">
<link href="https://fonts.googleapis.com/css2?family=Noto+Nastaliq+Urdu:wght@400;700&display=swap" rel="stylesheet">
```

#### Latin Script (Secondary)

```css
font-family: "Inter", "Segoe UI", "Helvetica Neue", sans-serif;
```

**Usage:** Technical terms, code snippets, numerical data, English labels, API names.

**Why Inter:** Designed for screens, excellent kerning at all sizes, modern and neutral.

### Font Sizes & Scale

**Base Unit:** 16px

| Level | Size | Line-Height | Usage |
|-------|------|-------------|-------|
| **Display XL** | 48px | 1.2 | Page titles |
| **Display Large** | 36px | 1.3 | Section headers |
| **Heading 1** | 32px | 1.4 | Major headings |
| **Heading 2** | 24px | 1.5 | Section subheadings |
| **Heading 3** | 20px | 1.6 | Component titles |
| **Body Large** | 18px | 1.8 | Lead paragraphs, intro text |
| **Body** | 16px | 1.8 | Standard body text, editorial |
| **Body Small** | 14px | 1.8 | Secondary text, captions |
| **Label** | 12px | 1.8 | Form labels, micro-copy |

### Line-Height (Critical for Nastaliq)

**Minimum line-height: 1.8**

Nastaliq has high vertical ascenders and deep descenders. Standard web line-heights (1.5) cause nuqtas (diacritical marks) to clip or overlap. 

**Enforcement:**
```css
body {
  line-height: 1.8;
}

/* Headings can compress slightly, but never below 1.4 */
h1, h2, h3 {
  line-height: 1.4;
}

/* Ensure body paragraphs maintain breathing room */
p {
  line-height: 1.9; /* Slightly more for readability */
}
```

### Font Rendering & Smoothing

```css
body {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  /* Keeps Nastaliq curves sharp and prevents blurry rendering */
  text-rendering: optimizeLegibility;
}

/* Prevent font-weight shifts during hover states */
button, a {
  transition: color 0.2s ease, background 0.2s ease;
  /* Do NOT animate font-weight; it causes layout shift */
}
```

### Font Weights

Only use:
- **400 (Regular):** Body text, standard labels
- **700 (Bold):** Headings, emphasis, strong text

**Avoid:** 300, 500, 600 (Noto Nastaliq doesn't render well at intermediate weights; design suffers).

---

## 4. Spacing & Layout Grid

**Base Unit:** 4px

All spacing follows a **modular scale** rooted in 4px. This allows for both fine-grained and large-scale alignments.

### Spacing Scale

| Name | Value | Usage |
|------|-------|-------|
| **xs** | 4px | Micro-spacing (inline elements, icon gaps) |
| **sm** | 8px | Component internal padding, tight grouping |
| **md** | 16px | Standard padding, default gaps |
| **lg** | 24px | Section spacing, moderate breathing room |
| **xl** | 32px | Large section gaps, hero spacing |
| **2xl** | 48px | Page-level spacing, major layout blocks |
| **3xl** | 64px | Full-screen spacing, viewport-scale gaps |

### Layout Principles

#### Horizontal (RTL-Aware)

In RTL context, directionality is reversed:
- **margin-inline-start:** Becomes right margin (logical property; auto-flips on RTL)
- **padding-inline-end:** Becomes left padding (logical property; auto-flips on RTL)

**Always use logical properties:**
```css
.component {
  /* ✅ GOOD: Auto-flips in RTL */
  margin-inline: 16px;
  padding-inline-start: 24px;

  /* ❌ BAD: Hard-coded LTR; breaks in RTL */
  margin-left: 16px;
  padding-right: 24px;
}
```

#### Vertical

Vertical spacing is **unaffected by RTL**. All vertical margins and paddings remain consistent.

```css
.card {
  padding-block: 24px;      /* 24px top + bottom */
  margin-block: 16px;       /* 16px top + bottom */
}
```

### Container & Card Spacing

```css
.card {
  padding: 24px;            /* Internal spacing */
  margin-block: 16px;       /* External spacing */
  border: 1px solid var(--color-border);
  border-radius: 8px;
  background: var(--color-bg-secondary);
}

.section {
  padding-block: 32px;      /* Vertical padding within section */
  padding-inline: 24px;     /* Horizontal padding (RTL-safe) */
}
```

### Grid System (Optional: 12-column)

For complex layouts, use a 12-column grid:
```css
.grid {
  display: grid;
  grid-template-columns: repeat(12, 1fr);
  gap: 16px;
  direction: rtl;           /* RTL grid automatically reverses columns */
}

.grid-col-6 {
  grid-column: span 6;
}

.grid-col-4 {
  grid-column: span 4;
}
```

---

## 5. Component Styles

### Buttons

#### Primary Button
```html
<button class="button button-primary">
  <span lang="ur">موافقہ</span>
</button>
```

```css
.button-primary {
  background: var(--color-primary);
  color: white;
  padding: 12px 24px;
  border: none;
  border-radius: 6px;
  font-family: var(--font-urdu);
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s ease;
}

.button-primary:hover {
  background: var(--color-primary-dark);
}

.button-primary:active {
  opacity: 0.9;
}

.button-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
```

#### Secondary Button
```html
<button class="button button-secondary">
  <span lang="ur">منسوخ</span>
</button>
```

```css
.button-secondary {
  background: var(--color-bg-secondary);
  color: var(--color-primary);
  padding: 12px 24px;
  border: 2px solid var(--color-primary);
  border-radius: 6px;
  font-family: var(--font-urdu);
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.button-secondary:hover {
  background: rgba(15, 89, 94, 0.1);
}
```

#### Icon Placement (RTL-Aware)

In RTL, icons should be placed on the **right (logical-right)** of the text:

```html
<!-- Urdu context (RTL) -->
<button class="button button-primary">
  <icon class="icon-send" aria-hidden="true"></icon>
  <span lang="ur">بھیجیں</span>
</button>

<!-- HTML rendered as: [icon] [text] (visually: [text] [icon] in RTL) -->
```

```css
.button {
  display: flex;
  align-items: center;
  gap: 8px;
  /* In RTL, flex automatically reverses; icon appears on right visually */
}

.button .icon {
  width: 20px;
  height: 20px;
}
```

### Form Components

#### Input Fields

```html
<div class="form-group">
  <label lang="ur" for="username">صارف کا نام</label>
  <input 
    id="username" 
    type="text" 
    class="input" 
    placeholder="اپنا صارف کا نام درج کریں"
    lang="ur"
    dir="rtl"
  />
</div>
```

```css
.form-group {
  margin-block: 16px;
  display: flex;
  flex-direction: column;
}

.form-group label {
  font-family: var(--font-urdu);
  font-size: 14px;
  font-weight: 700;
  color: var(--color-text-primary);
  margin-block-end: 8px;
  text-align: right;  /* Right-aligned for RTL labels */
}

.input {
  padding: 12px 16px;
  border: 1px solid var(--color-border);
  border-radius: 6px;
  font-family: var(--font-urdu);
  font-size: 16px;
  color: var(--color-text-primary);
  line-height: 1.8;
  direction: rtl;
}

.input::placeholder {
  color: var(--color-text-tertiary);
}

.input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(15, 89, 94, 0.1);
}

.input:disabled {
  background: var(--color-bg-secondary);
  color: var(--color-text-tertiary);
  cursor: not-allowed;
}
```

#### Accessibility: Placeholder vs. Label

**Never** rely on placeholder as the only label. Placeholders disappear on focus, breaking accessibility.

```html
<!-- ❌ BAD: No visible label -->
<input placeholder="صارف کا نام" />

<!-- ✅ GOOD: Label + placeholder both present -->
<label for="username">صارف کا نام</label>
<input id="username" placeholder="مثال: احمد علی" />

<!-- ✅ EXCELLENT: Label + aria-label for screen readers -->
<label for="username" lang="ur">صارف کا نام</label>
<input 
  id="username" 
  aria-label="صارف کا نام درج کریں"
  placeholder="احمد علی"
/>
```

### Cards

```html
<div class="card">
  <h3 lang="ur">کارڈ کا عنوان</h3>
  <p lang="ur">یہاں کارڈ کا مواد ہے۔</p>
</div>
```

